use soneflow::{FieldType, ZwtvStream, StreamFrame, FrameQualityV1, loudness_zwtv, loudness_zwst};
use soneflow::internals::{core::main_loudness::main_loudness, tables::{A0,DDF,DCB,LTQ,DLL,RAP}};
use std::hint::black_box as bb;
fn read()->u32 {let mut x=0;unsafe{std::arch::asm!("stmxcsr [{}]",in(reg) &mut x,options(nostack));}x}
fn write(x:u32){unsafe{std::arch::asm!("ldmxcsr [{}]",in(reg) &x,options(nostack));}}
const fn narrow(a:[f64;20])->[f64;20]{let mut o=[0.;20];let mut i=0;while i<20{o[i]=a[i] as f32 as f64;i+=1;}o}
const AA:[f64;20]=narrow(A0); const DD:[f64;20]=narrow(DDF); const CC:[f64;20]=narrow(DCB);
fn levels(s:&[f64;28])->[f64;3]{let mut e=[0.;11];for k in 0..11{let r=(0..DLL.len()).find(|&r| s[k]<=RAP[r]-DLL[r][k]).unwrap_or(DLL.len()-1);e[k]=10f64.powf((s[k]+DLL[r][k])/10.);}let mut l=[0.;3];for (k,(a,b)) in [(0,6),(6,9),(9,11)].into_iter().enumerate(){let sum=e[a..b].iter().sum::<f64>();if sum>0.{l[k]=10.*sum.log10();}}l}
#[inline(never)]fn reference(s:&[f64;28],f:FieldType)->[f64;21]{let s=bb(*s);let lo=levels(&s);let mut out=[0.;21];for k in 0..20{let x=if k<3{lo[k]}else{s[k+8]};let mut x=x-AA[k];if f==FieldType::Diffuse{x+=DD[k];}if x>LTQ[k]{let x=x-CC[k];let a=(0.0635f32 as f64)*10f64.powf(bb(LTQ[k])*0.025);let b=(0.75+0.25*10f64.powf(0.1*(x-LTQ[k]))).powf(0.25)-1.;out[k]=(a*b).max(0.);}}let c=(0.4f32 as f64)+(0.32f32 as f64)*out[0].powf(0.2);if c<=1.{out[0]*=c;}out}
fn dump(tag:&str,v:&[f64]){print!("{tag}");for x in v{print!(",{:016x}",x.to_bits());}println!();}
fn corpus(f:FieldType)->Vec<[f64;28]>{let mut v=Vec::new();for band in 0..20{let threshold=LTQ[band]+AA[band]-if f==FieldType::Diffuse{DD[band]}else{0.};let mut s=[-150.;28];if band>=3{s[band+8]=threshold;}else{let (a,b)= [(0,6),(6,9),(9,11)][band];let mut low=-100.;let mut high=100.;for _ in 0..90{let m=(low+high)/2.;s[a..b].fill(m);if levels(&s)[band]>threshold{high=m}else{low=m}}s[a..b].fill((low+high)/2.);}
for d in [-1e-6,-1e-12,0.,1e-12,1e-6,1.,50.]{let mut q=s;if band<3{let(a,b)=[(0,6),(6,9),(9,11)][band];for x in &mut q[a..b]{*x+=d;}}else{q[band+8]+=d;}v.push(q);}}
for b in 0..11{for x in [120f64.next_down(),120.,120f64.next_up()]{let mut s=[45.;28];s[b]=x;v.push(s);}}
let mut seed=0x7265616c_u64;for _ in 0..257{let mut s=[0.;28];for x in &mut s{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1);*x=-30.+150.*((seed>>11) as f64/((1u64<<53) as f64));}v.push(s);}v}
fn main(){let orig=read();let arg=std::env::args().nth(1).unwrap_or("rn".into());let ctl=orig & !0xe040;write(ctl);let sig:Vec<f64>=(0..9600).map(|i|{let t=i as f64/48000.;(0.013*(t*2.*std::f64::consts::PI*719.).sin()+0.007*(t*2.*std::f64::consts::PI*3101.).sin())*if i<3600{1.}else{0.37}}).collect();let corpora=[corpus(FieldType::Free),corpus(FieldType::Diffuse)];
if arg=="corpus"{for(fi,c)in corpora.iter().enumerate(){for(i,s)in c.iter().enumerate(){dump(&format!("input:{fi}:{i}"),s);}}write(orig);return;}if arg=="rn"||arg.starts_with("ftz"){if arg.starts_with("ftz"){let bits:u32=arg[3..].parse().unwrap();write(ctl|bits);}for (fi,f) in [FieldType::Free,FieldType::Diffuse].into_iter().enumerate(){for(i,s)in corpora[fi].iter().enumerate(){match main_loudness(s,f){Ok(n)=>dump(&format!("main:{fi}:{i}"),&n),Err(e)=>println!("main:{fi}:{i},ERR:{e:?}")}}if arg=="rn"{let b=loudness_zwtv(&sig,48000.,f).unwrap();dump(&format!("batch:{fi}:n"),&b.n);dump(&format!("batch:{fi}:specific"),&b.n_specific);dump(&format!("batch:{fi}:time"),&b.time_axis);dump(&format!("batch:{fi}:bark"),&b.bark_axis);let mut stream=ZwtvStream::new(f);let mut out=vec![StreamFrame::default();200];for(c,chunk)in sig.chunks(137).enumerate(){let n=stream.push(chunk,&mut out);for(j,o)in out[..n].iter().enumerate(){println!("stream:{fi}:{c}:{j},{},{:016x},{:016x},{}",o.t_frame_index,o.n.to_bits(),o.n_phon.to_bits(),o.flags.bits());}}let n=stream.flush(&mut out);for(j,o)in out[..n].iter().enumerate(){println!("flush:{fi}:{j},{},{:016x},{:016x},{}",o.t_frame_index,o.n.to_bits(),o.n_phon.to_bits(),o.flags.bits());}}}}
else {for(mode,bits)in [("down",0x2000),("up",0x4000),("zero",0x6000)]{write(ctl|bits);for(fi,f)in [FieldType::Free,FieldType::Diffuse].into_iter().enumerate(){for (i,s)in corpora[fi].iter().enumerate(){if let Ok(n)=main_loudness(s,f){dump(&format!("{mode}:{fi}:{i}"),&n);let r=reference(s,f);dump(&format!("ref:{mode}:{fi}:{i}"),&r);}}}assert!(loudness_zwtv(&sig,48000.,FieldType::Free).is_err());assert!(loudness_zwst(&sig,48000.,FieldType::Free).is_err());let mut stream=ZwtvStream::new(FieldType::Free);let mut out=vec![StreamFrame::default();200];let mut quality=vec![FrameQualityV1::default();200];assert!(stream.push_with_quality(&sig[..137],&mut out,&mut quality).is_err());let n=stream.push(&sig[..137],&mut out);let m=stream.flush(&mut out);println!("guard:{mode},batch_reject,quality_reject,legacy_push={n},flush={m}");}}
write(orig);}
